theme.customCss:
.site-header{background:color-mix(in srgb,var(--color-background) 92%,transparent);backdrop-filter:blur(12px);border-bottom:1px solid var(--color-border);transition:background 180ms ease,border-color 180ms ease,color 180ms ease}.site-header--at-top{position:absolute!important;top:0!important;left:0!important;width:100%!important;background:transparent!important;border-bottom-color:transparent!important;backdrop-filter:none!important;color:#fff!important}.site-header--at-top .site-header__link,.site-header--at-top .site-header__brand{color:#fff!important}.site-header--at-top .button--primary{background:#fff!important;color:var(--color-primary)!important}.site-header--at-top .site-header__logo{filter:drop-shadow(0 2px 14px rgba(0,0,0,.45))}
.site-header__inner{min-height:78px;text-transform:uppercase;letter-spacing:.08em}
.site-header__brand{font-family:var(--font-heading);font-size:1.05rem;font-weight:700}
.site-header__logo{width:42px;height:42px}
.site-header__link{border-radius:0;font-size:.78rem;text-transform:uppercase;letter-spacing:.12em}
.button{border-radius:0;text-transform:uppercase;letter-spacing:.11em;font-size:.78rem}
.button--primary{background:var(--color-primary);box-shadow:none}
.button--secondary{border-color:var(--color-primary);color:var(--color-primary)}
.section{padding:96px 0}
.section:first-child{padding-top:0}
.section--hero:first-child{min-height:calc(100vh - 132px);display:grid;align-items:end;padding:152px 0 76px;background-position:center;background-size:cover;color:#fff}
.section--hero:first-child h1,.section--hero:first-child p,.section--hero:first-child .kicker{color:#fff}
.section--hero:first-child .hero{display:block;max-width:760px}
.section--hero:first-child .hero__copy{gap:20px}
.section--hero:first-child h1{max-width:12ch;font-size:clamp(3.4rem,8vw,7rem);line-height:.92;font-weight:500}
.hero{gap:64px}
h1,h2{font-weight:520}
h2{font-size:clamp(2.2rem,4.8vw,4.8rem);max-width:13ch}
.kicker{color:var(--accent, var(--color-accent));letter-spacing:.18em}
.content-card{padding:0;border:0;border-top:1px solid var(--color-border);border-radius:0;background:transparent}
.content-card h3{font-family:var(--font-heading);font-size:1.55rem;font-weight:520}
.text-link{color:var(--color-primary);font-weight:800;text-transform:uppercase;letter-spacing:.1em;font-size:.8rem}
.hero-stats,.stat-grid{border-top:1px solid color-mix(in srgb,var(--color-border) 72%,transparent);border-bottom:1px solid color-mix(in srgb,var(--color-border) 72%,transparent);background:transparent}
.hero-stats div,.stat-grid div{padding:22px 24px;background:transparent}
.hero-stats dd,.stat-grid dd{font-family:var(--font-heading);font-weight:520}.section--hero:first-child .hero-stats dt,.section--hero:first-child .hero-stats dd{color:#fff!important}.section--hero:first-child .hero-stats{border-top-color:rgba(255,255,255,.42)!important;border-bottom-color:rgba(255,255,255,.42)!important}.section--hero:first-child .hero-stats div+div{border-left-color:rgba(255,255,255,.34)!important}
.testimonial-card,.timeline__item{border-radius:0;background:var(--color-surface);border:1px solid var(--color-border)}
.cta-band{border-radius:0;background:var(--color-primary);color:var(--color-primary-contrast)}
.cta-band h2,.cta-band p,.cta-band .kicker{color:var(--color-primary-contrast)}
.contact-method{border-radius:0;background:var(--color-surface)}
@media (max-width:760px){.section--hero:first-child{min-height:760px;padding:118px 0 54px}.section--hero:first-child h1{font-size:clamp(3rem,17vw,5rem)}}
.section--mediaGallery .hero-carousel__stage{aspect-ratio:16/10}
.section--mediaGallery .hero-carousel__stage img{object-fit:cover}
.section--mediaGallery .hero-carousel figcaption{font-family:var(--font-heading);font-size:1.05rem}
.site-footer__social-link{border-radius:999px}

.section--hero.page-hero:first-child{min-height:520px;padding:138px 0 64px;align-items:end}
.section--hero.page-hero:first-child .hero{display:block;max-width:820px}
.section--hero.page-hero:first-child h1{max-width:14ch;font-size:clamp(2.7rem,6vw,5.4rem)}
.section--hero.page-hero:first-child .hero__body{max-width:660px}
@media (max-width:760px){.section--hero.page-hero:first-child{min-height:560px;padding:112px 0 48px}}
.section--hero:first-child .badge-list li{color:#fff!important;border-color:rgba(255,255,255,.62)!important;background:rgba(255,255,255,.16)!important;text-shadow:0 1px 8px rgba(0,0,0,.45)}
.section--hero:first-child .button--secondary{color:#fff!important;border-color:rgba(255,255,255,.72)!important;background:rgba(255,255,255,.14)!important;text-shadow:0 1px 8px rgba(0,0,0,.36)}
.section--hero:first-child .button--secondary:hover,.section--hero:first-child .button--secondary:focus-visible{background:rgba(255,255,255,.24)!important}
.site-header__logo{width:min(210px,45vw);height:52px}
